window.REVIEW_DETAILS["ny_b1-77fc3f77cb6dfe9f"]={"key":"ny_b1-77fc3f77cb6dfe9f","group":"ny_b1","uid":"77fc3f77cb6dfe9f","rank":49,"title":"verity ledger pellhaven coverage strategy","occupation":"news_analysts_reporters_journalists","archetype":"authored_doc","subbatch":"corpus_b1","prompt":"You are the senior editor for The Verity Ledger, and Rosalie Duquesne, our board chair, needs a two-year coverage and sourcing strategy before the November funding cycle. Pellhaven Cannery is the town's largest employer, our largest source of tips, and our second-largest event sponsor, so the plan has to confront the fact that the sponsorship helps pay for the presence that makes plant-floor reporting possible while refusing or losing it would make that presence harder to sustain. Use the attached Pellhaven coverage and funding record, `pellhaven_coverage_funding_record.xlsx`, when describing the starting position and projecting the two years; do not add financial, audience, access, or incident figures that are not supported there. Produce `verity_ledger_pellhaven_strategy_memo.docx` in the top level of the working directory, using exactly that filename. It is for Rosalie, the funding committee, and the reporting team: some readers know our sourcing history and some do not, but this must be a decision-ready newsroom memo rather than a tutorial about journalism. Set out a practical policy for sourcing, funding, disclosure, and review through the end of the second year, compare the credible paths, and make one clear recommendation about the sponsorship and the coverage presence that goes with it. Explain what the newsroom knowingly gives up under that recommendation, how independence and sensitive-source handling will be protected, and how the board can tell whether the bet is still working in 2028. Keep it to no more than three pages, use plain language, distinguish reported facts from assumptions and projections, and make the same financial and coverage commitments agree wherever they recur. Do not turn the memo into a story about Pellhaven, reproduce case records, identify vulnerable tipsters, or include a step-by-step system or publishing tutorial. End with the decision itself, not a list of unanswered next steps.\n\n---\n\nThe files referred to above are in `references/`:\n\n- `references/pellhaven_coverage_funding_record.xlsx` — A supplied internal record of Pellhaven coverage, sponsorship, reporting access, source-risk incidents, audience value, and stated funding assumptions for the two-year planning horizon.\n\nWrite your finished work to the **top level of the current working directory**, using exactly these filenames:\n\n- `verity_ledger_pellhaven_strategy_memo.docx` — A two-year coverage and sourcing strategy memo for the board, funding committee, and reporting team. (Top-level working directory; exactly three pages or fewer; one clear recommendation; decision-ready rather than tutorial-like; distinguish source-supported facts from assumptions and projections; do not identify vulnerable tipsters or reproduce case records; end with the decision rather than open next steps.)\n\nNothing outside those filenames is collected. A correct file written anywhere else, or under any other name, scores zero.\n","inputs":[{"name":"package/public/reference_files/pellhaven_coverage_funding_record.xlsx","bytes":7107,"extension":".xlsx","url":"assets/997bcb158fbb502d15f91efdec74d3c3a64abfa103c9d28f33ad22a1d1b88502.xlsx","sha256":"997bcb158fbb502d15f91efdec74d3c3a64abfa103c9d28f33ad22a1d1b88502","preview":{"kind":"sheets","sheets":[{"name":"Pellhaven record","row_count":33,"rows":[{"r":"1","cells":["The Verity Ledger | Pellhaven coverage & funding record"]},{"r":"2","cells":["Internal planning extract — updated 2025-10-06"]},{"r":"4","cells":["Category","Period","Measure","Value","Unit","Status / context"]},{"r":"5","cells":["Funding","2024","Cannery sponsorship","72000","USD","Observed cash received; second-largest event sponsor"]},{"r":"6","cells":["Funding","2025","Cannery sponsorship","78000","USD","Observed cash received; largest employer and largest tip source"]},{"r":"7","cells":["Funding","2025","Share of newsroom operating budget","0.14","ratio","Observed; sponsorship is material, not controlling"]},{"r":"8","cells":["Coverage","2024","Plant-floor reporting presence","36","visits","Observed reporter visits"]},{"r":"9","cells":["Coverage","2025","Plant-floor reporting presence","40","visits","Observed reporter visits"]},{"r":"10","cells":["Sourcing","2024","Pellhaven-related tips received","58","tips","Observed; tips are leads, not publishable facts"]},{"r":"11","cells":["Sourcing","2025","Pellhaven-related tips received","64","tips","Observed; tips are leads, not publishable facts"]},{"r":"12","cells":["Sourcing","2024","Tips independently corroborated","31","tips","Observed internal count"]},{"r":"13","cells":["Sourcing","2025","Tips independently corroborated","34","tips","Observed internal count"]},{"r":"14","cells":["Source safety","2024","Retaliation concerns logged","1","incident","Observed; no identifying details retained here"]},{"r":"15","cells":["Source safety","2025","Retaliation concerns logged","2","incidents","Observed; no identifying details retained here"]},{"r":"16","cells":["Accuracy","2024","Published corrections tied to Pellhaven coverage","1","correction","Observed"]},{"r":"17","cells":["Accuracy","2025","Published corrections tied to Pellhaven coverage","2","corrections","Observed"]},{"r":"18","cells":["Audience","2024","Engaged readers on Pellhaven work","18400","readers","Observed annual total"]},{"r":"19","cells":["Audience","2025","Engaged readers on Pellhaven work","20100","readers","Observed annual total"]},{"r":"20","cells":["Source diversity","2024","Non-cannery source groups used","4","groups","Observed: workers, residents, regulators, suppliers"]},{"r":"21","cells":["Source diversity","2025","Non-cannery source groups used","5","groups","Observed"]},{"r":"22","cells":["Access","2025","Sponsor-linked access condition","1","statement","Observed: sponsorship helps fund presence; no guaranteed access"]},{"r":"23","cells":["Planning assumption","2026","Renewal sponsorship","80000","USD","Assumption: annual renewal at $80,000"]},{"r":"24","cells":["Planning assumption","2027","Renewal sponsorship","80000","USD","Assumption: annual renewal at $80,000"]},{"r":"25","cells":["Planning assumption","2026","Renewal presence target","40","visits","Assumption, contingent on access and staffing"]},{"r":"26","cells":["Planning assumption","2027","Renewal presence target","40","visits","Assumption, contingent on access and staffing"]},{"r":"27","cells":["Planning assumption","2026","Exit-path replacement funds","50000","USD","Assumption: diversified grant/member plan"]},{"r":"28","cells":["Planning assumption","2027","Exit-path replacement funds","60000","USD","Assumption: diversified grant/member plan"]},{"r":"29","cells":["Planning assumption","2026","Exit-path presence target","24","visits","Assumption after losing sponsor-supported capacity"]},{"r":"30","cells":["Planning assumption","2027","Exit-path presence target","24","visits","Assumption after losing sponsor-supported capacity"]},{"r":"31","cells":["Planning assumption","2026","Firewall and source-safety reserve","8000","USD","Assumption within renewal budget for independent review/security"]},{"r":"32","cells":["Planning assumption","2027","Firewall and source-safety reserve","8000","USD","Assumption within renewal budget for independent review/security"]},{"r":"33","cells":["Planning assumption","2026-27","Review trigger","material interference","text","Assumption: any attempt to condition funding/access on coverage"]},{"r":"35","cells":["Export note: figures are internal planning records; assumptions are marked explicitly."]}],"truncated":false}],"note":"值与公式提取，不还原原始排版；每表最多120行、30列。","embedded_image_count":0,"embedded_images":[]}}],"gold":[{"name":"package/private/gold/verity_ledger_pellhaven_strategy_memo.docx","bytes":40448,"extension":".docx","url":"assets/c9c58125b0d2cc3582b6fa412d3fc8c6633fd142aff7ed6d9d5083546acd192e.docx","sha256":"c9c58125b0d2cc3582b6fa412d3fc8c6633fd142aff7ed6d9d5083546acd192e","preview":{"kind":"text","text":"THE VERITY LEDGER\nPellhaven coverage & sourcing strategy\nDecision memo | To Rosalie Duquesne, board chair, funding committee & reporting team | 6 October 2025\nDecision in brief\nRenew the Pellhaven Cannery sponsorship for 2026–2027 at the planning assumption of $80,000 per year, with a written editorial firewall, prominent disclosure, and an $8,000 annual reserve for independent review and source safety. Keep a 40-visit annual plant-floor presence only as a capacity target—not a sponsor promise. This is a conditional renewal: if the cannery seeks influence over selection, framing, timing, headlines, unpublished material, or suppression, we suspend the arrangement and move to the exit path.\nWhy this is the call\nThe supplied record shows a real exchange: the cannery paid $72,000 in 2024 and $78,000 in 2025 (14% of the 2025 newsroom operating budget), and that support helps fund the presence that makes plant-floor reporting possible. The same record shows 36 visits in 2024 and 40 in 2025, 58/64 tips received, and 31/34 independently corroborated. Sponsorship is financially material and operationally useful; it is not evidence that coverage is legitimate, nor proof that management speaks for the community. Workers, residents, regulators, suppliers, and other affected people remain necessary perspectives.\nTwo credible paths (figures from the record; projections are assumptions)\nPath\nMoney (2026 / 2027)\nPresence assumption\nWhat we gain / give up\nConditional renewal (recommended)\n$80k / $80k cannery sponsorship; $8k/year reserve\n40 plant-floor visits/year, contingent on staffing/access\nCapacity and continuity; accepts perceived conflict and dependence on one sponsor\nDecline / exit\n$50k / $60k diversified replacement funds\n24 visits/year after sponsor-supported capacity ends\nLess sponsor pressure; gives up $30k in 2026 and $20k in 2027 versus renewal assumption, plus frequency/access\nThe renewal wins on practical reporting capacity and funding resilience over this two-year window, but only if the firewall is real. We knowingly accept the perception cost and the possibility that access narrows despite sponsorship. The exit path is cleaner symbolically, yet its assumptions reduce presence from 40 to 24 visits and leave a replacement shortfall; neither path guarantees tips, access, or audience results.\nOperating policy for 2026–2027\nEditorial control. Sponsorship buys no favorable coverage, access to unpublished material, prior copy approval, headline approval, timing control, or suppression. Editors—not development staff, sponsors, or the board—choose stories, framing, sources, corrections, and publication. Every Pellhaven story, event page, or other public material that could reasonably create a conflict perception carries a clear, prominent sponsorship disclosure. Development may discuss benefits and logistics but cannot see confidential source material or direct assignments. Any perceived conflict is logged to the editor-in-chief and board ethics liaison; the $8,000 reserve funds an outside review when needed.\nSourcing and safety. A plant-floor tip is a lead, never a publishable fact. Serious allegations require independent corroboration (documents, direct observation, or another genuinely independent source), not repetition among sponsor-linked contacts. Before exposing identity or identifying details, the reporter and editor assess retaliation, employment, and safety risk; minimize names and descriptors, restrict access to need-to-know staff, and never use a confidential tip to pressure, threaten, negotiate with, or obtain leverage over a source or subject. The cannery and any named subject receive a meaningful opportunity to respond before publication. Corrections are labeled and prominent; material errors are corrected promptly, and source challenges are reviewed on the record without revealing protected identities.\nCoverage focus and access. Prioritize worker safety and labor conditions; environmental and regulatory oversight; local economic decisions that affect residents; and the cannery’s suppliers and public contracts. Maintain access through scheduled reporting visits, public records, regulators, labor representatives, residents, and suppliers—not a sponsor-only channel. If access is withdrawn, the 40-visit figure is treated as missed capacity, not a reason to soften a story.\nMonitoring and the 2028 test\nAt each six-month review, the editor and board liaison compare: (1) source diversity—number of non-cannery source groups and share of consequential claims corroborated independently; (2) safety and accuracy—retaliation concerns, correction count, and time to resolve challenges; (3) public value—engaged readers (2024 baseline 18,400; 2025 baseline 20,100) plus evidence of resident/regulator use, not raw clicks alone; (4) capacity—visits completed against the 40-visit assumption; and (5) sustainability—cash received versus the $80,000 assumption and progress toward diversified replacement funds. These are indicators, not guarantees.\nIn the end-of-2027 review (reported to the board in early 2028), continue only if editorial decisions remained free of sponsor conditions, serious allegations met the corroboration standard, source-risk handling remained safe, non-cannery perspectives were present, and the renewal cash and presence assumptions were substantially workable. Any attempted interference, repeated uncorroborated publication, unsafe disclosure, or material funding/access miss triggers immediate renegotiation or termination and activates the exit plan.\nDecision\nApprove a conditional $80,000-per-year Pellhaven Cannery renewal for 2026–2027, a 40-visit annual capacity target, and the $8,000 annual independence/source-safety reserve. The Ledger knowingly gives up the cleanest appearance of separation and accepts that access may still tighten; in return it preserves reporting capacity while making independence, disclosure, verification, and a 2028 exit test non-negotiable.","truncated":false,"note":"DOCX 正文与表格单元格文字提取；不还原分页、字体与版式。","embedded_image_count":0,"embedded_images":[]}}],"rubric":[{"rubric_item_id":"r01","check":"file_introspection","category":"deterministic","criterion":"The submitted artifact is a readable DOCX with the exact required filename.","weight":1.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"File name and successful document opening.","grader_hint":"Inspect the working-directory filename and open the DOCX."},{"rubric_item_id":"r02","check":"geometry","category":"deterministic","criterion":"The memo is no more than three rendered pages.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Rendered page count.","grader_hint":"Render the DOCX with an office-compatible engine and count pages."},{"rubric_item_id":"r03","check":"substring","category":"deterministic","criterion":"The memo identifies The Verity Ledger, Pellhaven Cannery, and Rosalie Duquesne in the planning context.","weight":1.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Opening context.","grader_hint":"Search the rendered text."},{"rubric_item_id":"r04","check":"judge","category":"semantic","criterion":"The memo is written as a decision-ready internal newsroom strategy rather than a feature story, essay, or journalism tutorial.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Overall document form and tone.","grader_hint":"Judge whether a board committee and editors could use it to decide funding and coverage."},{"rubric_item_id":"r05","check":"substring","category":"deterministic","criterion":"The memo covers the full two-year horizon and names a meaningful 2028 review point or equivalent end-state test.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Time horizon and review language.","grader_hint":"Require both years and a forward-looking test, not merely a calendar."},{"rubric_item_id":"r06","check":"relational_predicate","category":"deterministic","criterion":"All baseline financial and operational figures used in the memo are traceable to the supplied workbook or are explicitly labeled assumptions.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Memo figures compared with workbook.","grader_hint":"Check every number and factual operational claim against the source; allow clearly labeled planning assumptions."},{"rubric_item_id":"r07","check":"relational_predicate","category":"deterministic","criterion":"The memo distinguishes historical or current facts, assumptions, and projections rather than presenting them as one undifferentiated factual record.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Labels, attribution, and wording around figures.","grader_hint":"Look for an intelligible distinction in prose or a compact notation."},{"rubric_item_id":"r08","check":"relational_predicate","category":"deterministic","criterion":"The memo states the sponsorship's financial significance and its connection to reporting presence without treating either relationship as proof of editorial legitimacy.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Funding and access analysis.","grader_hint":"Both economic dependence and operational access must be discussed, with no false inference from one to the other."},{"rubric_item_id":"r09","check":"relational_predicate","category":"deterministic","criterion":"The memo compares at least two credible sponsorship or funding paths, including the status quo or renewal path and a path that gives up the sponsorship.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Options comparison.","grader_hint":"Options must be materially different, not cosmetic variants of the same plan."},{"rubric_item_id":"r10","check":"judge","category":"semantic","criterion":"The comparison weighs editorial independence, source access, funding resilience, audience value, and practical reporting capacity rather than optimizing only one dimension.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Trade-off analysis.","grader_hint":"A short but balanced comparison earns credit; a one-factor financial argument does not."},{"rubric_item_id":"r11","check":"judge","category":"semantic","criterion":"The memo makes exactly one primary recommendation about whether and under what broad condition the sponsorship continues.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Recommendation statement.","grader_hint":"Do not credit 'either/or,' an unresolved menu, or multiple co-equal recommendations."},{"rubric_item_id":"r12","check":"judge","category":"semantic","criterion":"The recommendation is justified by the supplied evidence and by a defensible editorial-risk judgment, not by generic independence language alone.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Reasoning from record to call.","grader_hint":"The reader should be able to see why this path wins despite its cost."},{"rubric_item_id":"r13","check":"relational_predicate","category":"deterministic","criterion":"The memo names the principal sacrifice or risk accepted by the recommendation and does not claim to preserve every benefit simultaneously.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Explicit trade-off statement.","grader_hint":"Require a real relinquishment, such as money, access, frequency, or convenience."},{"rubric_item_id":"r14","check":"relational_predicate","category":"deterministic","criterion":"Financial commitments and coverage-presence commitments agree across the recommendation, projections, and monitoring language.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Cross-section consistency.","grader_hint":"Recalculate or reconcile repeated amounts, staffing/presence claims, and timing."},{"rubric_item_id":"r15","check":"relational_predicate","category":"deterministic","criterion":"Any projected outcome is tied to stated assumptions and is not presented as a guaranteed result.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Projection language.","grader_hint":"Look for conditional wording and identify the assumptions supporting each material projection."},{"rubric_item_id":"r16","check":"relational_predicate","category":"deterministic","criterion":"The strategy preserves editorial control over story selection, framing, timing, headlines, and publication decisions.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Editorial-independence policy.","grader_hint":"Credit a coherent control principle covering the actual points of sponsor influence."},{"rubric_item_id":"r17","check":"relational_predicate","category":"deterministic","criterion":"The memo separates fundraising or sponsorship staff from editorial decision-making and provides a credible way to manage conflicts.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Governance and firewall language.","grader_hint":"A vague promise to be independent is insufficient without an organizational separation or review mechanism."},{"rubric_item_id":"r18","check":"relational_predicate","category":"deterministic","criterion":"The memo calls for clear, prominent disclosure of the sponsorship relationship when coverage or public materials could reasonably create a conflict perception.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Disclosure policy.","grader_hint":"Check that disclosure is not limited to a private board record."},{"rubric_item_id":"r19","check":"relational_predicate","category":"deterministic","criterion":"The memo states that sponsorship does not purchase favorable coverage, access to unpublished material, prior copy approval, or suppression of reporting.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Sponsor-boundary language.","grader_hint":"Require the relevant negative boundary, not merely 'no interference.'"},{"rubric_item_id":"r20","check":"relational_predicate","category":"deterministic","criterion":"The sourcing policy treats plant-floor tips as leads requiring verification rather than as publishable facts.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Sourcing standard.","grader_hint":"Look for explicit lead-versus-confirmed-fact language and an expectation of independent corroboration."},{"rubric_item_id":"r21","check":"relational_predicate","category":"deterministic","criterion":"The memo provides a safe handling standard for vulnerable or anonymous tipsters, including identity minimization and protection from unnecessary disclosure.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Source-safety policy.","grader_hint":"Require practical protection principles without requiring confidential names or case details."},{"rubric_item_id":"r22","check":"relational_predicate","category":"deterministic","criterion":"The memo requires reporters to assess retaliation or employment risk before exposing a plant-floor source's identity or identifying details.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Risk assessment language.","grader_hint":"A generic confidentiality promise does not satisfy the pre-publication risk judgment."},{"rubric_item_id":"r23","check":"relational_predicate","category":"deterministic","criterion":"The memo sets a standard for corroborating serious allegations before publication and distinguishes corroboration from mere repetition.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Verification policy.","grader_hint":"Judge whether the standard would prevent a single-source allegation from being treated as established fact."},{"rubric_item_id":"r24","check":"relational_predicate","category":"deterministic","criterion":"The strategy includes a fair opportunity for the cannery or other named subjects to respond to material allegations.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Fairness and response language.","grader_hint":"Look for meaningful notice and response treatment, not a promise to quote every side equally."},{"rubric_item_id":"r25","check":"relational_predicate","category":"deterministic","criterion":"The memo discourages using confidential tips to pressure, threaten, negotiate with, or otherwise obtain leverage over a source or subject.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Explicit misuse prohibition.","grader_hint":"This must actively prohibit the misuse, not merely describe source confidentiality."},{"rubric_item_id":"r26","check":"relational_predicate","category":"deterministic","criterion":"The strategy addresses how corrections, source challenges, or newly discovered errors will be handled transparently.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Corrections and challenge policy.","grader_hint":"Require both a response to error and a public-facing accountability principle."},{"rubric_item_id":"r27","check":"judge","category":"semantic","criterion":"The memo gives an actionable boundary for reporters and editors without becoming a system click-through or a general journalism lesson.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Usability and level of detail.","grader_hint":"A new team member should know the governing boundary, but the memo should remain a strategy document."},{"rubric_item_id":"r28","check":"judge","category":"semantic","criterion":"The memo uses plain, specific language that a board reader unfamiliar with daily Pellhaven reporting can understand without flattening the editorial issues into a tutorial.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Audience accessibility.","grader_hint":"Evaluate jargon control, definitions of specialized terms, and whether context is sufficient."},{"rubric_item_id":"r29","check":"relational_predicate","category":"deterministic","criterion":"The memo identifies a limited set of coverage priorities or beats for the two-year period that reflect Pellhaven's public significance.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Coverage priorities.","grader_hint":"Priorities should be selective and public-interest based, not an unbounded promise to cover everything."},{"rubric_item_id":"r30","check":"relational_predicate","category":"deterministic","criterion":"The coverage plan includes a way to maintain or rebuild source access that is consistent with the chosen funding path.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Access and resourcing plan.","grader_hint":"Check the plan against the stated sponsorship decision and accepted sacrifice."},{"rubric_item_id":"r31","check":"relational_predicate","category":"deterministic","criterion":"The memo includes an editorially meaningful monitoring set for the two years, including source diversity or access, verification or correction experience, audience/public value, and financial sustainability.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Monitoring framework.","grader_hint":"Metrics must cover both journalism quality and sustainability; vanity metrics alone do not qualify."},{"rubric_item_id":"r32","check":"relational_predicate","category":"deterministic","criterion":"Monitoring measures are defined well enough to distinguish a healthy strategy from a strategy that merely produces more stories or more sponsor visibility.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Metric definitions and interpretation.","grader_hint":"Look for quality, independence, safety, or resilience indicators rather than raw volume only."},{"rubric_item_id":"r33","check":"relational_predicate","category":"deterministic","criterion":"The memo states what evidence would trigger reconsideration, adjustment, or termination of the chosen funding or coverage arrangement.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Review and exit conditions.","grader_hint":"Require concrete classes of evidence, not just 'review annually.'"},{"rubric_item_id":"r34","check":"relational_predicate","category":"deterministic","criterion":"The memo acknowledges that losing sponsorship may reduce reporting presence, access, or frequency and addresses that consequence honestly.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Downside analysis.","grader_hint":"Credit an explicit operational cost rather than a generic statement that there are trade-offs."},{"rubric_item_id":"r35","check":"relational_predicate","category":"deterministic","criterion":"The memo does not treat the largest employer's cooperation as equivalent to community consent or public-interest validation.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Independence and community framing.","grader_hint":"Look for recognition of affected residents, workers, and other stakeholders beyond management."},{"rubric_item_id":"r36","check":"relational_predicate","category":"deterministic","criterion":"The memo identifies at least one source or perspective outside the cannery's management and sponsorship relationship as necessary to credible coverage.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Source-diversity policy.","grader_hint":"The named category may vary, but it must widen the evidentiary base beyond sponsor-linked sources."},{"rubric_item_id":"r37","check":"relational_predicate","category":"deterministic","criterion":"The memo keeps confidential source identities and sensitive case details out of the strategy document while still stating the governing protection standard.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Document contents.","grader_hint":"Check for both meaningful policy and absence of identifying details."},{"rubric_item_id":"r38","check":"judge","category":"semantic","criterion":"The recommendation and its trade-off remain plausible in 2028 under the memo's own assumptions, rather than depending on an implausible permanent access or funding condition.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Long-horizon coherence.","grader_hint":"Judge whether the plan can survive changing sponsor relations, source conditions, and funding feedback."},{"rubric_item_id":"r39","check":"judge","category":"semantic","criterion":"The memo closes with the selected decision and accepted cost, not with a list of unresolved next steps or a request for the reader to choose among options.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Final paragraph.","grader_hint":"The ending must resolve the call while retaining appropriate caveats."},{"rubric_item_id":"r40","check":"constraint_predicate","category":"deterministic","criterion":"The memo does not reproduce confidential operational records, identify vulnerable tipsters, or include a step-by-step publishing or system tutorial.","weight":-5.0,"polarity":"penalty","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Rendered memo content.","grader_hint":"Apply the penalty if the document over-produces sensitive case detail or procedural system instruction beyond the requested strategy."}],"spec":{"professional_context":"This is a nonprofit newsroom planning memo in which editorial independence, source safety, access, and financial sustainability pull in different directions. The artifact must be usable by both newsroom and governance readers without exposing confidential operational details.","difficulty_sources":["Balancing sponsorship dependence, plant-floor access, source safety, and editorial independence without claiming all benefits can be retained","Projecting a two-year strategy from a single supplied operational and funding record","Writing a concise normative memo for governance and newsroom readers with different background knowledge","Making a singular recommendation that explicitly accepts a measurable trade-off"],"authoring_plan":{"reference_file":{"purpose":"Construct one offline XLSX source containing a compact, internally consistent factual record for the Verity Ledger's Pellhaven planning decision. It should include historical sponsorship amounts and timing, coverage presence or effort, tip and source patterns, audience or public-value indicators, any documented editorial-risk or correction events, and explicit two-year planning assumptions or scenario inputs. Include records involving Pellhaven Cannery and, where useful for comparison or alternative public-interest sourcing, Kilnbrook Agricultural and Lampwick Authority. Use synthetic values and synthetic internal records only.","constraints":["The source must make at least two credible paths analyzable: continuing or renewing the sponsorship with independence safeguards, and declining or ending it with a different funding/access consequence.","The evidence must create a genuine tension: sponsorship materially supports the presence or capacity used for plant-floor reporting, while the relationship creates a meaningful perceived or actual independence risk.","Include enough data for the solver to calculate or reconcile a two-year financial and coverage projection, but do not encode a recommended answer.","Include explicit assumptions that a competent planner can use, and distinguish them from observed historical records.","Include at least one source-safety or editorial-risk record that supports the need for verification, confidentiality, or corrections policy without exposing any real or identifying person.","Ensure all figures and relationships used by the rubric are present in a discoverable form and internally consistent.","Do not require an invented local code, template, sheet name, or private convention in the solver output."]},"gold_document":{"intended_verdict":"A strong gold memo makes one defensible recommendation, preferably one that accepts a real sacrifice rather than promising both unrestricted sponsorship benefits and perfect independence. It uses the workbook's figures consistently, treats sponsorship-linked tips as leads rather than proof, protects vulnerable sources, sets sponsor boundaries and disclosure, and provides a bounded two-year monitoring and reconsideration framework.","required_content_constraints":["Keep the memo within three pages while covering the recommendation, options, trade-off, funding and presence implications, sourcing safeguards, mixed-audience clarity, monitoring, and 2028 review logic.","The common misuse to actively discourage is using confidential tips or sponsor-linked access as leverage, or publishing unverified allegations as established fact; the gold must prohibit the misuse rather than merely describe it.","The mixed audience consists of governance readers who need concise context and newsroom readers who need usable boundaries; the gold should define necessary terms briefly without becoming a tutorial.","The recommendation must be singular and the final paragraph must state the decision and what is knowingly given up.","The gold must not identify tipsters, reproduce case records, invent unsupported figures, or promise mutually incompatible outcomes."]},"derivation":"Build the workbook first, then draft a memo using only its observed values and labeled assumptions. Reconcile repeated amounts and coverage commitments mathematically, render the DOCX to verify the page limit, and review the result against every rubric item independently. The rubric is relational so alternate legitimate numerical instances remain scorable."},"design_constraints":{"artifact_scope":"single_artifact","structure":"strict_schema"},"reference_files":[{"artifact_id":"pellhaven_coverage_funding_record","filename":"pellhaven_coverage_funding_record.xlsx","purpose":"A supplied internal record of Pellhaven coverage, sponsorship, reporting access, source-risk incidents, audience value, and stated funding assumptions for the two-year planning horizon.","required":true,"discovery":"The workbook is supplied with the task; use it as the sole factual source for baseline figures and projections."}],"deliverables":[{"deliverable_id":"strategy_memo","filename":"verity_ledger_pellhaven_strategy_memo.docx","media_type":"application/vnd.openxmlformats-officedocument.wordprocessingml.document","description":"A two-year coverage and sourcing strategy memo for the board, funding committee, and reporting team.","required":true,"constraints":["Top-level working directory; exactly three pages or fewer; one clear recommendation; decision-ready rather than tutorial-like; distinguish source-supported facts from assumptions and projections; do not identify vulnerable tipsters or reproduce case records; end with the decision rather than open next steps."],"rendering_required":true}],"work_activity":"communicate_stakeholders","work_product":"news_editorial_package","internet_policy":"forbidden","evidence_policy":"closed_world_with_assumptions"},"source_metadata":{"prompt_version":"authored_doc@v4","occupation":"news_analysts_reporters_journalists","sector":"information","task_archetype":"authored_doc","estimated_professional_hours":5.5,"gold_policy_self_report_not_verified":{"author_type":"hybrid","reviewer_policy":"Have a newsroom-management reviewer verify strategic usefulness, editorial-independence and source-safety standards, and a separate reviewer reconcile every figure and projection against the supplied workbook and check the rendered page cap.","minimum_reviewers":2,"known_limitations":["Professional judgments about the balance between access, independence, and financial resilience cannot be reduced entirely to literal checks; the judge items require newsroom editorial expertise."],"reference_solution_passed_rubric":true}},"validation":{"label":"成品包存在","detail":"按公开题面存在纳入抽样；不视为内容正确性验收。","formal":false,"release_ready_recorded":true,"checks":[{"check":"package_integrity","validator":"gdpval-package","validator_version":"v1","passed":true,"required":true,"metrics":{},"evidence_artifact_ids":[],"detail":"","checked_at":"2026-08-20T18:56:45+00:00"},{"check":"gold_isolation","validator":"gdpval-package","validator_version":"v1","passed":true,"required":true,"metrics":{},"evidence_artifact_ids":[],"detail":"","checked_at":"2026-08-20T18:56:45+00:00"},{"check":"artifact_format","validator":"gdpval-package","validator_version":"v1","passed":true,"required":true,"metrics":{},"evidence_artifact_ids":[],"detail":"","checked_at":"2026-08-20T18:56:45+00:00"},{"check":"rendering","validator":"gdpval-package","validator_version":"v1","passed":true,"required":true,"metrics":{},"evidence_artifact_ids":[],"detail":"","checked_at":"2026-08-20T18:56:45+00:00"},{"check":"instruction_rubric_overlap","validator":"gdpval-package","validator_version":"v1","passed":false,"required":false,"metrics":{},"evidence_artifact_ids":[],"detail":"instruction 与 rubric criterion 存在 8-gram 逐字重叠: ['r40']","checked_at":"2026-08-20T18:56:45+00:00"}]},"source_path":"/inspire/hdd2/project/special-project-1/public/ynan/gdpval_data/corpus_b1/runs/77fc3f77cb6dfe9f","declared_deliverables":["verity_ledger_pellhaven_strategy_memo.docx"]};
